function compareScore(a, b) {
  const x = BigInt(a);
  const y = BigInt(b);
  return x < y ? -1 : x > y ? 1 : 0;
}

module.exports = { compareScore };
const test = require('node:test');
const assert = require('node:assert');
const { compareScore } = require('../src/score');

test('compares beyond 2^53', () => {
  assert.strictEqual(compareScore('9007199254740993', '9007199254740992'), 1);
  assert.strictEqual(compareScore('10', '9'), 1);
});
